/** Attributes bundled bytes to source modules via the sourcemap, so
 *  "how much of the shipped JS is dev-only code?" is measured, not guessed. */
import { readFileSync } from "node:fs";

const mapPath = process.argv[2];
const map = JSON.parse(readFileSync(mapPath, "utf8"));
const bundleSize = readFileSync(mapPath.replace(/\.map$/, ""), "utf8").length;

// Decode mappings: count generated bytes attributed to each source index.
const VLQ = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function decodeVlq(str) {
  const out = []; let shift = 0, value = 0;
  for (const ch of str) {
    const d = VLQ.indexOf(ch);
    if (d === -1) continue;
    const cont = d & 32;
    value += (d & 31) << shift;
    if (cont) { shift += 5; }
    else { const neg = value & 1; value >>= 1; out.push(neg ? -value : value); value = 0; shift = 0; }
  }
  return out;
}

const bytesBySource = new Map();
let srcIdx = 0;
const lines = map.mappings.split(";");
// Approximate: attribute each segment's generated-column span to its source.
for (const line of lines) {
  let genCol = 0;
  const segs = line.split(",").filter(Boolean);
  const decoded = segs.map(decodeVlq);
  for (let i = 0; i < decoded.length; i++) {
    const d = decoded[i];
    genCol += d[0];
    if (d.length >= 4) {
      srcIdx += d[1];
      const next = i + 1 < decoded.length ? genCol + decoded[i + 1][0] : genCol;
      const span = Math.max(0, next - genCol);
      const src = map.sources[srcIdx] ?? "(unknown)";
      bytesBySource.set(src, (bytesBySource.get(src) ?? 0) + span);
    }
  }
}

const rows = [...bytesBySource.entries()]
  .map(([src, bytes]) => [src.replace(/^.*?(packages|apps|node_modules)\//, "$1/"), bytes])
  .sort((a, b) => b[1] - a[1]);

const total = rows.reduce((a, b) => a + b[1], 0);
console.log(`bundle: ${bundleSize} bytes; attributed: ${total}\n`);
console.log("=== per module ===");
for (const [src, bytes] of rows) {
  console.log(String(bytes).padStart(7), (bytes / total * 100).toFixed(1).padStart(5) + "%", src);
}

const DEV = /rotation-test|debug-lab|bug-repro|layer-debug|entityPreview/;
const devBytes = rows.filter(([s]) => DEV.test(s)).reduce((a, b) => a + b[1], 0);
console.log(`\n=== dev/debug-only modules ===`);
for (const [s, b] of rows.filter(([s]) => DEV.test(s))) console.log(String(b).padStart(7), s);
console.log(`TOTAL dev-only: ${devBytes} bytes = ${(devBytes / total * 100).toFixed(1)}% of attributed bundle`);
